import { useReset } from '../../utils/ReactHypercube/useReset';
import { useHypercubeContext } from '../../HypercubeContext';

import ControlPanel from './ControlPanel';
import ReactHypercube from '../../utils/ReactHypercube';

import style from './styles.module.css';

const HypercubeSandbox = () => {
	const { environmentType, restart, selectedFOV, setMoveForwardFn, setMoveBackwardFn, setAnimationA, setAnimationB } = useHypercubeContext();

	const instanceKey = useReset(restart);
	const debuggerMode = true;

	return (
		<div className={style.hypercubeEnv}>
			<div>
				<ControlPanel panelBody={'sandbox'} />
			</div>

			<div className={style.hypercubeDivWrapper}>
				<div className={style.hypercubeDiv}>
					<ReactHypercube
						debuggerMode={debuggerMode}
						key={instanceKey}
						environmentType={environmentType}
						webGPU={true}
						performanceMode={false}
						fov={selectedFOV}
						setMoveForwardFn={setMoveForwardFn}
						setMoveBackwardFn={setMoveBackwardFn}
						animationA={setAnimationA}
						animationB={setAnimationB}
					/>
				</div>
			</div>
		</div>
	);
};

export default HypercubeSandbox;
